cat > tests/test_contacts.py <<'EOF'
# owner: platform
import unittest

from rosterkit.reader import read_roster
from rosterkit.models import Student
from rosterkit.contacts import contact_rows
from tests.support import data_file


def make_student(last, first, section="A", email="x@y.edu"):
    return Student("1", last, first, section, email)


class ContactRowTests(unittest.TestCase):
    def test_rows_sorted_by_name(self):
        rows = contact_rows(
            [make_student("Varrow", "Ines"),
             make_student("Thistle", "Bram")]
        )
        self.assertTrue(rows[0].startswith("Thistle, Bram"))
        self.assertTrue(rows[1].startswith("Varrow, Ines"))

    def test_columns_line_up(self):
        rows = contact_rows(
            [make_student("Ng", "Al", "B", "al@y.edu"),
             make_student("Longername", "Bea", "C", "b@y.edu")]
        )
        self.assertEqual(
            rows[0], "Longername, Bea     C        b@y.edu"
        )
        self.assertEqual(
            rows[1], "Ng, Al               B        al@y.edu"
        )

    def test_missing_email_names_student(self):
        roster = [make_student("Thistle", "Bram", email=None)]
        with self.assertRaises(ValueError) as caught:
            contact_rows(roster)
        self.assertIn("Thistle, Bram", str(caught.exception))

    def test_blank_email_is_missing(self):
        with self.assertRaises(ValueError):
            contact_rows([make_student("Ng", "Al", email="")])

    def test_empty_list(self):
        with self.assertRaises(ValueError):
            contact_rows([])

    def test_sample_roster(self):
        students = read_roster(data_file("roster.csv"))
        try:
            rows = contact_rows(students)
        except ValueError as exc:
            self.assertIn(", ", str(exc))
        else:
            self.assertEqual(len(rows), len(students))
EOF
